const recallCards=[["若一个氨基酸的 pH 高于 pI，它通常带什么净电荷？","通常偏负。pH 升高使基团更易去质子化；pH>pI 时，平均净电荷从零继续向负方向移动。"],["为什么 pI 不能理解为“分子没有电荷”？","pI 时平均净电荷为零，但两性离子形式同时含有 –NH₃⁺ 和 –COO⁻。"],["为什么 Gly 在 Ramachandran 图上允许范围更大？","Gly 的侧链是 H，空间位阻小，因此更多 φ/ψ 组合不发生原子重叠。"],["为什么 Pro 常打断 α 螺旋？","Pro 限制 φ 并常缺少可用于螺旋主链氢键的 N–H，因此常破坏 α 螺旋。"],["肽键近似平面，蛋白质为什么还能折叠？","ω 转动受限，但相邻的 φ 和 ψ 单键仍可旋转；它们的受限组合塑造整个主链。"],["α 螺旋的关键氢键在哪里？","第 n 个残基的主链 C=O 与第 n+4 个残基的主链 N–H 之间。"],["β 折叠的“平行/反平行”描述什么？","相邻 β 股的 N→C 方向关系，而非两张片层是否完全平行摆放。"],["模体与结构域的尺度差别是什么？","模体是局部重复组合；结构域更大，常可相对独立折叠并承担功能。"],["Anfinsen 法则真正说明什么？","一级序列含有形成天然构象所需的化学信息，前提是条件合适；它不否定细胞内伴侣的作用。"],["分子伴侣怎样帮助折叠？","它们暂时遮蔽暴露疏水表面或提供隔离空间，减少错误聚集，并不替蛋白决定最终序列信息。"],["为什么 Cys 二硫键在胞质中通常不稳定？","胞质环境通常较还原，会促进二硫键还原为两个巯基。"],["His 为什么常见于活性位点？","咪唑基 pKa 接近生理 pH，较容易在结合或催化过程中给出或接受质子。"]];const quizzes=[{q:"蛋白质 X 的某 Lys 侧链处于 pH 10 的环境。相对 pH 7，它更可能发生什么变化？",a:["更易质子化","更易失去质子","必然形成二硫键","转变为 D-构型"],c:1,e:"pH 上升推动可电离基团去质子化。Lys 的具体比例还取决于局部微环境和 pKa。"},{q:"某突变把一个螺旋内部的 Leu 换成 Pro。最直接的结构风险是？",a:["肽键全部变成 cis","α螺旋局部被破坏","产生新的二硫键","蛋白必然降解"],c:1,e:"Pro 限制 φ 并常缺少可用于螺旋主链氢键的 N–H，因此常破坏 α 螺旋；后续命运需实验判断。"},{q:"为什么同一序列可能在不同条件下呈不同构象集合？",a:["一级结构毫无作用","环境改变了溶剂化、质子化和相互作用代价","肽键可以任意旋转","所有结构都等能"],c:1,e:"序列提供倾向，而 pH、氧化还原状态、配体和拥挤程度会改变能量景观。"},{q:"一个 β 股的侧链通常朝哪里分布？",a:["都朝片层中央","交替伸向片层两面","都沿氢键方向","完全随机"],c:1,e:"β 折叠近似伸展的锯齿状主链使侧链交替位于片层两侧。"},{q:"Anfinsen 实验不能直接推出下面哪一项？",a:["序列含有折叠信息","细胞中从不需要分子伴侣","适当条件下 RNase A 可复性","折叠受自由能驱动"],c:1,e:"细胞内存在聚集、翻译过程和拥挤等问题；许多蛋白需要伴侣辅助。"},{q:"若要区分“pI”与“pKa”，最准确的说法是？",a:["两者都只属于溶液","pI 是净电荷为零的 pH，pKa 描述单个电离步骤","pKa 是蛋白质大小","pI 一定等于 7"],c:1,e:"pKa 关联某个可电离基团和其环境；pI 是整个分子电荷状态的结果。"}];function renderRecall(){const host=document.querySelector('#recall-card');if(!host)return;let i=Number(localStorage.getItem('bio-recall-index')||0)%recallCards.length;const draw=()=>{const [q,a]=recallCards[i];host.innerHTML=`<p class="eyebrow">CARD ${i+1} / ${recallCards.length}</p><h2>${q}</h2><button class="primary" id="reveal">显示答案</button><div id="answer" hidden><p>${a}</p><div class="rate"><button data-rate="again">还不会</button><button data-rate="hard">有点模糊</button><button data-rate="good">能完整讲出</button></div></div>`;host.querySelector('#reveal').onclick=()=>{host.querySelector('#answer').hidden=false;host.querySelector('#reveal').hidden=true};host.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{localStorage.setItem('bio-recall-index',String((i+1)%recallCards.length));i=(i+1)%recallCards.length;draw()})};draw()}function renderPractice(){const host=document.querySelector('#quiz-list');if(!host)return;host.innerHTML=quizzes.map((x,i)=>`<article class="quiz"><p class="eyebrow">QUESTION ${i+1}</p><h3>${x.q}</h3>${x.a.map((a,j)=>`<button data-q="${i}" data-a="${j}">${String.fromCharCode(65+j)}. ${a}</button>`).join('')}<p class="explain" hidden></p></article>`).join('');host.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const x=quizzes[+b.dataset.q],card=b.closest('.quiz');card.querySelectorAll('button').forEach(k=>k.disabled=true);b.classList.add(+b.dataset.a===x.c?'correct':'wrong');card.querySelectorAll('button')[x.c].classList.add('correct');const e=card.querySelector('.explain');e.hidden=false;e.textContent=x.e})}renderRecall();renderPractice();
